// 4. Three-way match: invoice ≤ delivered and ≤ ordered per item code
const po = e.po ? { ...e.po, items: e.po.items || (arch.archive_po && arch.archive_po.read ? arch.archive_po.line_items : null) } : null;
const dn = e.dn ? { ...e.dn, items: e.dn.items || (arch.archive_dn && arch.archive_dn.read ? arch.archive_dn.line_items : null) } : null;
let match = 'no_po_reference';
if (inv.order_number) {
  if (!po) match = 'po_not_found';
  else if (!dn) match = 'delivery_not_found';
  else if (!po.items || !dn.items || !po.items.length || !dn.items.length) match = 'unknown';
  else {
    const q = (list, code) => list.filter((x) => x.code === code).reduce((s, x) => s + x.quantity, 0);
    const bad = inv.line_items.filter((it) => it.code && (it.quantity > q(dn.items, it.code) || it.quantity > q(po.items, it.code)));
    match = bad.length ? 'quantity_mismatch' : 'ok';
    if (bad.length) findings.push('Billed more than delivered or ordered: ' + bad.map((b) => b.code + ' × ' + b.quantity).join(', ') + '.');
  }
}
checks.order = match === 'ok' ? 'ok' : 'finding';
if (match === 'po_not_found') findings.push('Order ' + inv.order_number + ' was not found in this scan or your workspaces.');
if (match === 'delivery_not_found') findings.push('No delivery note found for order ' + inv.order_number + '.');
if (match === 'no_po_reference') findings.push('The invoice has no order number.');
if (match === 'unknown') findings.push('Order or delivery note could not be read.');
// 5. Order already billed by other invoice(s)
let over_billed = false;
const po_total = po ? (po.total ?? (arch.archive_po ? arch.archive_po.total_amount : null)) : null;
if (e.billed_by.length) {
  checks.billed = 'finding';
  const sum = e.billed_by.reduce((s, b) => s + (Number(b.total) || 0), 0) + (Number(inv.total_amount) || 0);
  findings.push('Order ' + inv.order_number + ' is already billed by ' + e.billed_by.map((b) => (b.invoice_number || b.file_name || '?') + ' (' + (b.origin === 'approved' ? 'approved' : (b.origin === 'this scan' ? 'this scan' : 'not yet decided')) + (b.total ? ', ' + Number(b.total).toFixed(2) : '') + ')').join(', ') + '. Check the remaining quantity before paying.');
  if (po_total && sum > Number(po_total) + 0.01) { over_billed = true; findings.push('All invoices for order ' + inv.order_number + ' together (' + sum.toFixed(2) + ') exceed the order total (' + Number(po_total).toFixed(2) + ').'); }
} else checks.billed = 'ok';
const rejected_for_order = Array.isArray(e.rejected_for_order) ? e.rejected_for_order : [];
if (rejected_for_order.length) { checks.billed = 'finding'; findings.push('A rejected invoice exists for the same order ' + inv.order_number + ': ' + rejected_for_order.map((b) => b.invoice_number || b.file_name || '?').join(', ') + ' (quarantine).'); }
if (inv.family === 'credit_note') findings.push('This is a credit note. Check it against the invoice it corrects.');
const risk = findings.length === 0 ? 'low' : (iban_status === 'changed' || iban_status === 'quarantine' || checks.duplicate === 'finding' || over_billed ? 'high' : 'medium');
const groups4 = (v) => String(v || '').replace(/\s+/g, '').replace(/(.{4})(?=.)/g, '$1 ');
const sum_qty = (d, code) => (d && d.items ? d.items.filter((x) => x.code === code).reduce((s, x) => s + x.quantity, 0) : null);
const lines = [
  'AP inbox check (n8n) — ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC',
  'Scan: ' + $('Settings').first().json.scan_name + ' · document ' + inv.index + (inv.pages ? ' (pages ' + inv.pages + ')' : '') + (inv.split_review !== 'ok' ? ' · split needs review' : ''),
  'Supplier: ' + (inv.supplier || '?') + ' · Invoice: ' + (inv.invoice_number || '?') + ' · Total: ' + (inv.total_amount ?? '?') + ' ' + inv.currency,
  'IBAN check: ' + iban_status + ' · Duplicate: ' + checks.duplicate + ' · Order/delivery: ' + match,
  'Risk: ' + risk + (findings.length ? '' : ' — no findings, approval by a reviewer is still required'),
  ...findings.map((f) => '• ' + f),
  '',
  'Read from the invoice:',
  '• Invoice ' + (inv.invoice_number || '?') + (inv.invoice_date ? ' of ' + inv.invoice_date : '') + (inv.due_date ? ' · due ' + inv.due_date : '') + ' · order ' + (inv.order_number || 'none'),
  '• IBAN on the invoice: ' + (inv.iban ? groups4(inv.iban) : 'none found'),
  '• Known IBANs of this supplier (approved invoices): ' + (e.history_ibans.length ? e.history_ibans.map(groups4).join(', ') : 'none found'),
  ...((e.quarantine_ibans || []).length ? ['• IBANs on rejected invoices (quarantine): ' + e.quarantine_ibans.map(groups4).join(', ')] : []),
  ...(inv.line_items.length
    ? ['• Items (invoiced / delivered / ordered):', ...inv.line_items.map((it) => '  ' + (it.code || '?') + ': ' + it.quantity + ' / ' + (sum_qty(dn, it.code) ?? '–') + ' / ' + (sum_qty(po, it.code) ?? '–'))]
    : ['• Items: none read']),
  'Compared with: order ' + (po ? po.name + ' (' + po.source + ')' : 'not found') + ' · delivery note ' + (dn ? dn.name + ' (' + dn.source + ')' : 'not found'),
  '',
  'No payment is released by this workflow. The reviewer decides.',
];
return [{ json: { pofid: inv.pofid, name: inv.name, agent_uuid: inv.agent_uuid, invoice_number: inv.invoice_number, supplier: inv.supplier, risk, findings, iban_check: { status: iban_status, check_id: 'iban_changed' }, duplicate: checks.duplicate, order_match: match, report: lines.join('\n') } }];

// Result of this round. Loop over invoices collects it and hands all results to "Summarize run".
const ev = $('Evaluate checks').first().json;
const q = ($json.body !== undefined ? $json.body : $json) || {};
const code = Number($json.statusCode || 0);
return [{ json: { pofid: ev.pofid, name: ev.name, invoice_number: ev.invoice_number, supplier: ev.supplier, risk: ev.risk, findings: ev.findings, iban_check: ev.iban_check.status, order_match: ev.order_match, queued: code >= 200 && code < 300, task_uuid: q.task_uuid || null, queue_message: code >= 300 ? (q.message || q.code || ('HTTP ' + code)) : '' } }];

// One line per invoice, plus the other documents of the scan that were archived as evidence.
const results = $input.all().map((i) => i.json).filter((r) => r.pofid);
const others = $('Read fields').all().map((i) => i.json).filter((d) => d.family !== 'invoice' && d.family !== 'credit_note');
const label = { order: 'order', delivery_note: 'delivery note', other: 'other document' };
const lines = results.map((r) => (r.invoice_number || r.name) + ' (' + (r.supplier || '?') + '): risk ' + r.risk.toUpperCase() + ', IBAN ' + r.iban_check + ', order/delivery ' + r.order_match + (r.queued ? ' — queued for review' : ' — NOT queued: ' + r.queue_message));
const title = results.length ? results.length + ' invoice' + (results.length > 1 ? 's' : '') + ' checked · ' + results.filter((r) => r.queued).length + ' queued for human review' : 'No invoice found in the scan';
const message = [...lines, others.length ? 'Archived as evidence: ' + others.map((d) => label[d.family] + ' ' + d.name).join(', ') + '.' : '', 'No payment was released.'].filter(Boolean).join(' · ');
return [{ json: { title, message, results } }];

// Compares X-PaperOffice-Signature with the HMAC computed by "Compute signature" over the RAW body (constant-time).
// Works without the "crypto" module, so it runs on n8n Cloud and self-hosted alike. Anything missing → invalid → 401.
const hook = $('Review decision').first().json;
const headers = hook.headers || {};
const sig = String(headers['x-paperoffice-signature'] || '');
const raw = String($('Read raw body').first().json.raw_body || '');
const expected = 'sha256=' + String($input.first().json.expected_signature || '');
let valid = raw.length > 0 && expected.length === 71 && sig.length === expected.length;
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= (sig.charCodeAt(i) || 0) ^ expected.charCodeAt(i);
valid = valid && diff === 0;
let payload = {};
try { payload = JSON.parse(raw); } catch (e) { payload = {}; }
return [{ json: { valid, event: String(headers['x-paperoffice-event'] || payload.event_type || ''), event_id: String(headers['x-paperoffice-event-id'] || payload.event_id || ''), data: payload.data || {} } }];

// ── Archive settings ─────────────────────────────────────────────────────────
const APPROVED_WORKSPACE_ID = 0;        // approved invoices are moved here
const QUARANTINE_WORKSPACE_ID = 0;      // rejected or escalated invoices are moved here and put on legal hold
const LOCK_APPROVED_WITH_WORM = false;  // true = WORM retention lock on approved invoices (paid, cannot be undone)
// ─────────────────────────────────────────────────────────────────────────────
if (!(Number(APPROVED_WORKSPACE_ID) > 0) || !(Number(QUARANTINE_WORKSPACE_ID) > 0)) throw new Error('Enter the approved and quarantine workspace IDs in the "Archive settings" node.');
// Only a reviewers' approval counts as approved. Escalation, rejection or anything else goes to quarantine.
const d = $json.data || {};
const approved = $json.event === 'hitl.review.consensus_completed' && String(d.final_decision || '') === 'approve';
if (!d.pofid) throw new Error('The decision has no document (pofid).');
return [{ json: { pofid: String(d.pofid), approved, decision: d.final_decision || $json.event, task_uuid: d.task_uuid || '', event_id: $json.event_id,
  target_workspace_id: Number(approved ? APPROVED_WORKSPACE_ID : QUARANTINE_WORKSPACE_ID), worm: Boolean(LOCK_APPROVED_WITH_WORM) } }];
